def calc_tally(tup, op):
    tally = [0, 0]
    for price in tup.values():
        tally[0] += price  # cost
        if op == '+':
            tally[1] += price  # inventory saving
        else:
            tally[1] -= price  # inventory taking
    return tuple(tally)


