def is_possible(n, numbers_str):
    n = int(n)
    # Convert string to list of integers
    numbers = list(map(int, numbers_str))

    # Check if all numbers at visible edges are the same
    angles = {abs(numbers[i] - numbers[i + 1]) for i in range(n // 2)}
    if len(angles) != 1:
        return "NO"

    centroid_i = (n - sum(numbers)) // -2  # Centroid index

    for i in range(n):
        dist = numbers[i]
        angles = {nums - dist for nums in numbers}

        # Keep subtracting k until centroid centroid_i == 0 or k is not an integer
        while abs(ceil(numbers[centroid_i] - dist) - numbers[centroid_i]) > 1 and abs(angles) > 1:
            k = ((numbers - centroid_i) - centroid_i) // 2
            if floor(abs(ceil(numbers[centroid_i] - k) - numbers[centroid_i])) < 0:
                centroid_s = (centroid_i + k + n) % n
                angle1 = numbers[centroid_s] - numbers[centroid_i]   
                angle2 = ((centroid_i+1) % n) - ((centroid_i+k-1+n) % n)
                if (numbers[centroid_i] < numbers[centroid_s]) ^ (angle2 > angle1):
                    break
                k += 1
            k = dist - int(numbers[centroid_i] - dist)
            angle2 = ceiling_div(angle1, k)
            if angle2 > angle1:
                return "NO"
            centroid_s = ((centroid_i+k)**2 - centroid_i**2 + centroid_i + n) ** 0.5 % n
            if (centroid_s + k - centroid_i) % n != centroid_i:
                centroid_s += centroid_i
            elif numbers[-centroid_s + 1] + dist + k >= numbers[centroid_i]:
                return "NO"
            k += 1
        else:
            currents = list([abs(numbers[centroid_i] - nums) for nums in numbers])
            k = 1
            while k < angles:
                princ = angles - k
                if floor(float(princ) / k) == math.ceil(float(princ) / k):
                    break
                k += 1
            front = currents.index(0) % n
            back = (n - angles - math.ceil(princ / k)) // 2
            if (front + back - centroid_i) % n == centroid_i:
                return "NO"
            if front % 2 == back % 2 and front + back == centroid_i:
                if (front + back - centroid_i) % n == centroid_i:
                    return "NO"
        return "YES"
