def is_palindrome(s):
    return s == s[::-1]

def can_make_numbers_zero(n, numbers):
    if n == 3:
        # For only three points, if the frequency of 0, 1, and 3 is one of the same number, it's possible
        return numbers.count(0) == (numbers.count(1) ^ numbers.count(3))

    for i in range(2, n):
        if len(set(numbers[::i])) > i:
            # If there are more than i unique values within the set (representing equally spaced points), it's not possible
            return False

