def min_substring_length(s, queries):
    def two_approx(s, q):
        lo, hi = 0, len(s)
        while lo < hi:
            mid = (lo + hi) // 2
            if compare_len(s[:mid], q) <= compare_len(s[mid:], q):
                hi = mid
            else:
                lo = mid + 1
        return s[:lo]

    def compare_len(s1, s2):
        i = 0
        n1, n2 = len(s1), len(s2)
        for i in range(min(n1, n2)):
            if s1[i] != s2[i]:
                return ord(s1[i]) - ord(s2[i])
        return 0 if i == min(n1, n2) else -1 if n1 > n2 else 1

    results = []
    for query in queries:
        result = two_approx(s, query)
        results.append(result[:len(result) - 1]) if result[-1] != len(result) else results.append(result)
    return results

