def find_min_length_suffix(s, prefix_var, suffix_var):
    prefix_index = 0
    suffix_index = len(s) - 1 - len(suffix_var) + 1
    min_len = float('inf')
    while prefix_index < len(prefix_var) and suffix_index < len(suffix_var):
