from bisect import bisect_left, bisect_right
from math import ceil

MAX, MIN = 998244353 * 2, 998244353

def k_beautiful_count(l, r, k):
    prev = None
    count_left = [0] * (MAX + 1)
    count_right = [0] * (MIN - 1)
    for num in range(l, r + 1):
        if num > MAX:
            if num > 999999:
                first, second = divmod(num, 10)
                if abs(first - second) > k:
                    return count_right[second] - count_left[first]
            elif num > 999998:
                first, second = divmod(num, 10)
                if first > second + k:
                    return count_left[second] - count_right[first]
            else:
                first = num // 100000
                second = num // 10 - 100 * first
                return count_right[second] - count_left[first]
        else:
            if prev is None:
                prev = str(num)[-1]
            else:
                prev = str(num)[-1]
        first = num // 10_000_000_000
        second = ceil((num - first * 10_000_000_000) / 10_000_000 - first * 10)
        if first > 0:
            # Validate first left sum
            idx = bisect_left(count_left, second)
            if idx < len(count_left) and count_left[idx] > first * 10 + second // 10:
                idx -= 1
            # Validate second left sum
            idx = bisect_left(count_left, idx)
            if idx < len(count_left) and count_left[idx] > first > second // 10:
                idx -= 1
            if idx < len(count_left):
                return count_left[idx] - count_left[first]
        else:
            idx = bisect_left(count_right, first)
            if idx < len(count_right) and count_right[idx] > first * k:
                return count_right[first] - count_right[first - k + 1]

