    def traverse(x, y, visited):
        if (x, y) in side_cases:
            return
        side_cases.append((x, y))
        visited.add((x, y))
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx = x + dx
            ny = y + dy
            if (nx, ny) in arr and (nx, ny) not in arr:
                traverse(nx, ny, visited)

    for i, point in enumerate(arr):
        dx, dy = point
        if (dx, dy) in arr:
            continue
        if len(neg) == 0:
            if (dx, dy) in neg_neighbours:
                continue
            traverse(dx, dy, set())
            n = len(neg_neighbours)
            move = dx//4*n + n//2
            if i >= move:
                side_cases.append((dx, dy))
            del arr[i:i+n+1]
            continue
        for j in range(move):
            neg.insert(j, (dx, dy))
            traverse(dx, dy, set())
        del arr[i:i+move+1]

    for i in range(len(arr)):
        if arr[i] in neg:
            side_cases.append(arr[i])
            neg.remove(arr[i])
    return side_cases

