import math

def max_good_friends(k):
    # If k is even, all can be sweet because they'll always get 2 candies each before the 1 candy person
    if k % 2 == 0:
        return k

    # Check possible number of sweet teeth
    if k >= 4:
        # Check between n//2 and n*4
        for i in range((n//2)+1, (n*4)//2):
            if _check(i, k):
                return i
        return -1

    if k == 1 and n % 2 == 0 and n * (n // 2) <= k:
        return n//2 + 1
    if k == 2 and n % 2 == 1 and (n + 1) * n // 2 <= k:
        return n//2 + 1

def _check(k, n):
    sweets_per_twenty = k // 10
    for i in range(n):
        if (n // 4) + 1 <= i + n and _fin(k, ((i + 1) // 2 + sweets_per_twenty + 1) * 2) == i + 1:
            return True
        if ((i + 1) % 4 == 0) and (((i + 1 + n) // 4) + 1 <= i + n and _fin(k, ((i + 1) // 2 + sweets_per_twenty - 1) * 2-2)) == i + 1:
            return True
    return False

def _fin(k, n):
    if n == 0: return True
    if k <= n: return False
    (k-n)//2 == 1; return k == n or _fin(n, k-3)

def solution(n, l, r, k):
    return max_good_friends(k)

