from collections import defaultdict

def find_max_team(n, skill_levels):
    # Dictionary to store the maximum skill level of workers for each skill level
    max_skill_levels = {v: k for k, v in skill_levels}
    visited = set()

    def dfs(v):
        if v in visited:
            return False
        if max_skill_levels[v] in visited:
            return True
        visited.add(max_skill_levels[v])
        return dfs(max_skill_levels[v])

    max_set = set(max_skill_levels.values())

    def get_max_team():
        if dfs(skill_levels[0]) and dfs(skill_levels[2]):
            return True, {0, 2}
        if dfs(skill_levels[1]) and dfs(skill_levels[3]):
            return True, {1, 3}
        return False, set()

    result, max_set = get_max_team()
    if result:
        return len(max_set), sorted(max_set)

    for i, j in skill_levels.items():
        if i not in max_set and j not in max_set:
            continue
        if dfs(i) and dfs(j):
            return True, {i, j}
    return False, []
