from collections import defaultdict

def max_happiness(likenesses_friday, likeliness_saturdays):
    num_employees = len(likenesses_friday)
    graph_friday, graph_saturdays = defaultdict(list), defaultdict(list)

    # Build graph for Fridays
    for i in range(num_employees):
        for j in range(num_employees):
            if likenesses_friday[i][j] > 0:
                graph_friday[i].append((likinesses_friday[i][j], j))

    # Build graph for Saturdays
    for i in range(num_employees):
        for j in range(num_employees):
            if likeliness_saturdays[i][j] > 0:
                graph_saturdays[i].append((likeliness_saturdays[i][j], j))

    max_happiness = 0

    # Helper function to find max happiness for a specific week, starting from a person i with happiness h
    def dfs(person, happiness):
        nonlocal max_happiness, graph_friday, graph_saturdays
        happiness += graph_friday[person][0][1] * 0.5
        for happiness, club in graph_saturdays[person]:
            happiness += happiness
            max_happiness = max(max_happiness, dfs(club, happiness))

    # Try every person as potential Friday clubbing subject
    for person in range(num_employees):
        dfs(person, 0)

    return max_happiness


