def is_vertical_polygon_crossing_horizontal(pts):
    n = len(pts)
    horizontal_hits = [0, 0]  # counts vertical line to the left and to the right
    for i in range(n):
        x, y, _ = pts[i]
        if x == 0 and y != 0:  # no need to consider edges parallel with the y-axis
            if y == -1 and horizontal_hits[0] > 0:
                return True
            elif y == 1 and horizontal_hits[1] > 0:
                return True
        x -= pts[(i+1) % n][0]
        left = x < 0
        right = x > 0
        if y < 0:
            if left and right:
                horizontal_hits[left] += 1
            elif left == right and left:
                horizontal_hits[1-left] += 1
        elif y > 0:
            if left and right:
                horizontal_hits[1-left] += 1
            elif left == right and right:
                horizontal_hits[left] += 1
    return False

