import sys
import math

def calculate_distance(point1, point2):
    return math.sqrt((point2[0] - point1[0])**2 + (point2[1] - point1[1])**2)

def calculate_area_of_intersection(pt1, pt2, r1, r2):
    d = calculate_distance(pt1, pt2)
    if d > r1 + r2:
        # The closest points of the two circles do not overlap
        return 0
    if d <= abs(r1 - r2):
        # One circle is contained in the other
        return 1 if d < r1 - r2 else 0
    # Use the principle of subtraction of areas
    return math.acos((r1**2 + r2**2 - d**2) / (2 * r1 * r2)) * 2 + 1 - math.acos((r2**2 + d**2 - r1**2) / (2 * r2 * d))

def calculate_connected_components(shape, points):
    visited = set()
    for point in points:
        if point not in visited:
            visited.add(point)
            stack = [point]
            while stack:
                new_stack = []
                for p in stack:
                    if p in shape:
                        shape.remove(p)
                    for d in range(-1, 2):
                        for u in range(-1, 2):
                            new_points = (p[0] + d, p[1] + u)
                            if new_points in shape and new_points not in visited:
                                new_stack.append(new_points)
                                visited.add(new_points)
                stack = new_stack
    return len(visited)

def find_shape_intersection(shape, jellyfish):
    intersections = {}
    for i in range(len(jellyfish)):
        for k in range(i + 1, len(jellyfish)):
            current_shape = set([jellyfish[i], jellyfish[k]])
            for point in shape:
                if calculate_distance(point, [jellyfish[i][0], jellyfish[i][1]]) < jellyfish[i][2] and calculate_distance(point, [jellyfish[k][0], jellyfish[k][1]]) < jellyfish[k][2]:
                    count = calculate_area_of_intersection(point, [jellyfish[i], jellyfish[k]], current_shape)
                    if count:
                        if count not in intersections:
                            intersections[count] = [current_shape]
                        else:
                            intersections[count].append([current_shape])
    return intersections

def maximize_jellyfish_intersection(shape, jellyfish):
    intersections = find_shape_intersection(shape, jellyfish)
    chosen = 0
    best = float('inf')
    for key in intersections:
        for item in intersections[key]:
            total = len(item)
            if total < best:
                chosen = total
                best = total
    return chosen

def solve(pool_size, boat_shape, jellyfish):
    boat_points = [(0, -pool_size), (0, pool_size)]
    empty_area = 0
    for point in boat_shape:
        empty_area += calculate_connected_components(boat_points, [point])
    min_jellyfish = calculate_connected_components(jellyfish, boat_points) - empty_area
    return min_jellyfish

